        insert into tbl_problems (problem_id, question, description, difficulty, user_id, created_at, permit_yn)
values  (1, '부서별 평균 급여를 계산하는 SQL을 작성하시오.', '부서별 평균 급여를 구하기 위해 `AVG()` 함수를 사용합니다. 부서 ID를 기준으로 `GROUP BY`를 사용하여 각 부서별 평균 급여를 계산할 수 있습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (2, '모든 직원의 정보를 조회하는 SQL을 작성하시오.', '`SELECT * FROM employees;` 명령어를 사용하면 테이블의 모든 데이터를 조회할 수 있습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (3, '전체 직원 수를 조회하는 SQL을 작성하시오.', '`COUNT()` 함수를 사용하면 특정 컬럼을 기준으로 전체 데이터 개수를 구할 수 있습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (4, '부서 ID가 10인 직원들의 정보를 조회하는 SQL을 작성하시오.', '`WHERE` 절을 사용하여 특정 조건을 만족하는 데이터를 필터링할 수 있습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (5, '직원들의 이름을 알파벳 순으로 정렬하여 조회하는 SQL을 작성하시오.', '`ORDER BY` 절을 사용하면 특정 컬럼을 기준으로 정렬할 수 있습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (6, '데이터베이스에서 PRIMARY KEY의 역할로 적절한 것은 무엇인가?', 'PRIMARY KEY는 테이블 내에서 **고유한 값**을 가지며, 한 행(row)을 **유일하게 식별**하는 역할을 합니다. 중복된 값이 들어갈 수 없으며, NULL 값도 허용되지 않습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (7, 'WHERE 절을 사용할 때 올바른 예제는 무엇인가?', 'WHERE 절은 특정 조건을 만족하는 데이터만 필터링하여 조회할 때 사용됩니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (8, 'INNER JOIN이 수행하는 기능은 무엇인가?', 'INNER JOIN은 두 개 이상의 테이블을 조인할 때, **공통된 값이 있는 행만 반환**하는 방식입니다. 조건을 만족하는 데이터만 결과에 포함됩니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (9, 'ORDER BY 절의 역할은 무엇인가?', 'ORDER BY 절은 특정 컬럼을 기준으로 데이터를 정렬할 때 사용됩니다. `ASC`는 오름차순(기본값), `DESC`는 내림차순 정렬을 의미합니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (10, 'GROUP BY와 함께 사용할 수 있는 함수로 적절한 것은 무엇인가?', 'GROUP BY는 특정 컬럼을 기준으로 데이터를 그룹화할 때 사용되며, 보통 **집계 함수(Aggregate Function)** 와 함께 사용됩니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (11, '기본 키(Primary Key)와 외래 키(Foreign Key)의 차이점으로 올바른 것은?', '기본 키는 **테이블 내에서 각 행을 유일하게 식별하는 역할**을 하며, 외래 키는 **다른 테이블의 기본 키를 참조하는 컬럼**으로, 테이블 간 관계를 설정하는 데 사용됩니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (12, 'UNIQUE 키의 특징으로 적절한 것은?', 'UNIQUE 키는 컬럼 내에서 **중복된 값을 허용하지 않는 제약 조건**입니다. 그러나 **NULL 값은 허용**할 수 있습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (13, 'SQL에서 테이블 및 컬럼 이름(식별자)으로 사용할 수 없는 것은?', 'SQL에서 테이블이나 컬럼 이름으로 **예약어(Reserved Keywords)** 를 사용하면 오류가 발생할 수 있습니다. 일부 키워드는 큰따옴표(") 또는 백틱(`)으로 감싸면 사용할 수도 있습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (14, 'SQL에서 AUTO_INCREMENT가 적용될 수 있는 데이터 타입은?', 'AUTO_INCREMENT는 **자동으로 숫자가 증가하는 속성**이며, 일반적으로 정수(INT)형 컬럼에 사용됩니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (15, 'SQL에서 NULL이 의미하는 것은 무엇인가?', 'NULL은 **값이 존재하지 않음을 의미하는 특별한 상태**이며, 0이나 빈 문자열과는 다릅니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (16, 'employees 테이블에서 부서 ID가 3인 직원들의 모든 정보를 조회하는 SQL을 작성하시오.', '부서 ID가 3인 직원들만 필터링하려면 `WHERE` 절을 활용해야 합니다. `SELECT * FROM employees WHERE department_id = 3;`', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (17, 'employees 테이블에서 가장 높은 급여를 받는 직원의 정보를 조회하는 SQL을 작성하시오.', '급여가 가장 높은 직원을 찾으려면 `ORDER BY`와 `LIMIT 1`을 활용할 수 있습니다. `SELECT * FROM employees ORDER BY salary DESC LIMIT 1;`', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (18, '부서 ID가 2인 직원 중 가장 낮은 급여를 받는 직원의 정보를 조회하는 SQL을 작성하시오.', '특정 부서에서 최저 급여를 받는 직원을 찾으려면 `WHERE`과 `ORDER BY`, `LIMIT 1`을 함께 사용할 수 있습니다. `SELECT * FROM employees WHERE department_id = 2 ORDER BY salary ASC LIMIT 1;`', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (19, 'employees 테이블에서 모든 직원의 평균 급여를 조회하는 SQL을 작성하시오.', '평균 급여를 구하려면 `AVG()` 집계 함수를 사용합니다. `SELECT AVG(salary) FROM employees;`', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (20, '각 부서별 직원 수를 계산하고, 직원 수가 5명 이상인 부서를 조회하는 SQL을 작성하시오.', '직원 수를 세려면 `GROUP BY`와 `HAVING`을 함께 사용해야 합니다. `SELECT department_id, COUNT(*) FROM employees GROUP BY department_id HAVING COUNT(*) >= 5;`', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (21, 'PRIMARY KEY의 역할에 대한 설명으로 알맞은 것은?', 'PRIMARY KEY는 테이블에서 각 행을 고유하게 식별하는 역할을 합니다. 또한, NULL 값을 가질 수 없으며 중복이 허용되지 않습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (22, 'FOREIGN KEY(외래 키)의 역할에 대한 설명으로 알맞은 것은?', 'FOREIGN KEY는 다른 테이블의 PRIMARY KEY를 참조하는 키입니다. 테이블 간의 관계를 정의하고 데이터 무결성을 보장하는 역할을 합니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (23, 'INDEX(인덱스)의 역할로 올바른 것은?', 'INDEX는 데이터 검색 속도를 향상시키는 역할을 합니다. 하지만 무분별하게 사용하면 오히려 성능이 저하될 수 있습니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (24, 'DDL과 DML의 차이로 올바른 것은?', 'DDL(Data Definition Language)은 테이블을 생성/삭제하는 명령어이고, DML(Data Manipulation Language)은 데이터를 삽입/수정/삭제하는 명령어입니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (25, '트랜잭션(Transaction)의 4가지 속성(ACID) 중 하나가 아닌 것은?', 'ACID는 원자성(Atomicity), 일관성(Consistency), 고립성(Isolation), 지속성(Durability)의 약자입니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (26, 'SQL에서 VIEW(뷰)의 역할로 올바른 것은?', 'VIEW는 실제 테이블이 아니라 특정 쿼리 결과를 저장하는 가상의 테이블입니다. 주로 보안, 데이터 일관성 유지, 복잡한 쿼리 단순화를 위해 사용됩니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (27, 'INNER JOIN과 OUTER JOIN의 차이로 올바른 것은?', 'INNER JOIN은 두 테이블 간 공통된 값이 있는 행만 반환하고, OUTER JOIN은 한쪽 테이블에만 존재하는 행도 반환합니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (28, '다음 중 서브쿼리(Subquery)의 올바른 사용법은?', '서브쿼리는 쿼리 내부에 포함된 또 다른 쿼리로, 주로 `WHERE`, `HAVING`, `FROM` 절에서 사용됩니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (29, 'GROUP BY와 HAVING의 차이로 올바른 것은?', 'GROUP BY는 데이터를 그룹화하는 데 사용되며, HAVING은 그룹화된 결과에 대한 조건을 지정하는 데 사용됩니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (30, 'DEFAULT 제약 조건의 역할로 올바른 것은?', 'DEFAULT 제약 조건은 컬럼에 값이 제공되지 않을 때 기본값을 설정하는 역할을 합니다.', 'EASY', 1, '2025-03-19 15:30:32', 'Y'),
        (31, '각 직원의 부서명과 급여를 함께 조회하는 SQL을 작성하시오.', 'employees 테이블과 departments 테이블을 JOIN하여 부서명과 급여를 함께 출력해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (32, '각 부서에서 급여가 가장 높은 직원의 ID, 급여, 부서명을 가져오시오.', '서브쿼리를 활용하여 각 부서별 최대 급여를 받는 직원을 조회해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (33, 'ACID 원칙의 각 개념을 올바르게 설명한 것은?', 'ACID 원칙은 트랜잭션의 신뢰성을 보장하는 중요한 개념입니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (34, '각 부서에서 직원 수가 5명 이상인 부서의 부서명을 조회하시오.', 'HAVING 절을 활용하여 특정 조건을 만족하는 그룹만 조회해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (35, '데이터베이스 정규화(Normalization)의 주요 목표는 무엇인가?', '정규화는 데이터 중복을 줄이고 무결성을 유지하기 위한 중요한 과정입니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (36, '각 부서에서 직원 수가 가장 많은 부서의 부서명을 조회하는 SQL을 작성하시오.', '서브쿼리를 활용하여 직원 수가 가장 많은 부서를 찾고 해당 부서명을 조회해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (37, '부서명이 "IT"인 직원들의 직원 ID와 이름을 조회하는 SQL을 작성하시오.', 'INNER JOIN과 WHERE 절을 활용하여 특정 부서의 직원 정보를 조회해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (38, '중복되지 않은 부서명을 조회하는 SQL을 작성하시오.', 'DISTINCT 키워드를 활용하여 부서명을 중복 없이 출력해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (39, '평균 급여가 5000 이상인 부서의 부서명과 평균 급여를 가져오시오.', 'HAVING 절을 사용하여 특정 기준을 충족하는 그룹을 필터링해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (40, '현재 근무하는 직원과 퇴사한 직원의 이름을 모두 가져오는 SQL을 작성하시오.', 'UNION을 사용하여 두 개의 서로 다른 데이터를 하나로 합쳐야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (41, '각 직원의 상사 ID 및 상사 이름을 함께 조회하시오.', 'SELF JOIN을 활용하여 같은 테이블 내에서 관계를 설정해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (42, '트랜잭션을 사용하여 계좌 이체를 실행하는 SQL을 작성하시오.', '트랜잭션과 COMMIT, ROLLBACK을 활용하여 데이터의 일관성을 유지해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (43, 'UNION과 UNION ALL의 차이점에 대한 설명으로 올바른 것은?', 'UNION과 UNION ALL은 결과를 합치는 기능이 있지만 동작 방식이 다릅니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (44, '각 부서에서 가장 높은 급여를 받는 직원의 ID와 급여를 조회하는 SQL을 작성하시오.', '각 부서에서 최고 급여를 받는 직원 정보를 가져오기 위해 서브쿼리를 활용해야 합니다. WHERE 절에서 비교를 수행하도록 해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (45, '부모 테이블에서 특정 데이터를 삭제할 때, 자식 테이블에 해당 데이터가 존재하면 삭제되지 않는 이유는 무엇인가?', '외래 키(Foreign Key) 제약 조건이 걸려 있을 경우, 부모 테이블의 데이터를 삭제하려면 자식 테이블의 데이터를 먼저 삭제해야 합니다. 이 문제는 관계형 데이터베이스에서 데이터 무결성을 보장하는 중요한 개념입니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (46, '각 부서별 직원 수를 조회하는 SQL을 작성하시오.', '각 부서에 속한 직원 수를 구하려면 GROUP BY 절을 사용해야 합니다. COUNT 함수를 활용하여 특정 기준에 따라 데이터를 그룹화하여 집계할 수 있습니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (47, '각 부서에 속한 서로 다른 직책(job_title)의 개수를 조회하는 SQL을 작성하시오.', '중복을 제거하고 고유한 값을 세려면 DISTINCT와 COUNT 함수를 함께 사용해야 합니다. 각 부서별로 직책의 개수를 집계하는 방식으로 해결할 수 있습니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (48, '각 학생의 평균 학점을 계산하여, 평균 학점이 3.5 이상인 학생만 조회하는 SQL을 작성하시오.', '학생들의 학점을 저장하는 `grades` 테이블이 있고, 각 학생의 성적 정보를 `student_id`를 기준으로 그룹화해야 합니다. 평균 학점을 계산하기 위해 `AVG()` 함수를 사용하며, 조건을 만족하는 학생만 조회하려면 `HAVING` 절을 활용해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (49, '가장 많이 주문된 상품(product_id)과 주문 횟수를 조회하는 SQL을 작성하시오.', '고객의 주문 기록을 저장하는 `orders` 테이블이 있으며, 주문된 상품 정보는 `product_id` 컬럼에 저장됩니다. 가장 많이 주문된 상품을 찾으려면 `COUNT()` 함수를 사용하고, `ORDER BY` 절을 활용하여 결과를 정렬해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (50, '현재 대출 중인 도서 목록을 조회하는 SQL을 작성하시오.', '도서 대출 정보를 저장하는 `library_loans` 테이블이 있으며, 반납 여부를 확인하는 `return_date` 컬럼이 있습니다. 현재 대출 중인 도서를 조회하려면 `return_date`가 `NULL`인 레코드만 선택해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (51, '2024년 5월에 주문된 주문 목록을 조회하는 SQL을 작성하시오.', '주문 정보를 저장하는 `orders` 테이블이 있으며, 주문 날짜는 `order_date` 컬럼에 저장됩니다. 특정 연도와 월에 해당하는 주문을 조회하려면 `YEAR()`, `MONTH()` 또는 `DATE_FORMAT()` 함수를 활용해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (52, '학생들의 평균 성적을 저장하는 `student_avg_scores` 뷰를 생성하는 SQL을 작성하시오.', '학생들의 성적 정보는 `grades` 테이블에 있으며, 각 학생의 평균 성적을 저장하는 뷰를 생성해야 합니다. 뷰는 `CREATE VIEW` 문을 사용하여 생성되며, 학생 ID와 평균 점수를 포함해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (53, '부서별 평균 급여보다 높은 급여를 받는 직원들을 조회하는 SQL을 작성하시오.', '각 부서의 평균 급여를 계산한 후, 해당 평균보다 높은 급여를 받는 직원만 조회해야 합니다. 이를 위해 `HAVING` 절이 아니라 `WHERE` 절과 서브쿼리를 활용해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (54, '상품의 가격을 기준으로 등급을 나누어 조회하는 SQL을 작성하시오.', '상품 테이블(`products`)에서 가격(price)이 50000원 이상이면 "고가", 20000원 이상이면 "중가", 그렇지 않으면 "저가"로 분류하여 조회해야 합니다. `CASE` 문을 활용하여 각 상품의 등급을 표시하세요.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (55, '신규 고객과 기존 고객을 구분하여 조회하는 SQL을 작성하시오.', '`customers` 테이블에는 고객 ID와 가입일(`join_date`) 정보가 있습니다. 2023년 이후 가입한 고객을 "신규 고객", 그 이전 가입한 고객을 "기존 고객"으로 분류하여 조회하세요. `UNION`을 사용하여 두 개의 쿼리 결과를 하나로 합쳐야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (56, '주문 테이블에서 특정 주문을 취소할 때 트랜잭션을 활용하는 SQL을 작성하시오.', '트랜잭션을 사용하여 `orders` 테이블에서 주문을 취소(`status`를 "CANCELLED"로 변경)하고, 동시에 결제(`payments`) 정보를 삭제하는 SQL을 작성하세요. 오류가 발생하면 전체 작업이 롤백되어야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (57, '각 직원이 속한 부서에서 연봉 순위를 매기는 SQL을 작성하시오.', '`employees` 테이블에서 직원의 ID, 이름, 부서 ID, 연봉 정보를 가져온 후, 같은 부서 내에서 연봉 순위를 매겨 "연봉 순위"를 추가해야 합니다.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (58, '각 직원의 상사 이름을 함께 조회하는 SQL을 작성하시오.', '`employees` 테이블에서 직원의 ID, 이름과 함께 해당 직원의 상사(manager)의 이름을 가져와야 합니다. SELF JOIN을 활용하여 상사-직원 관계를 표현하세요.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (59, '직원 이메일 주소에서 도메인 부분만 추출하는 SQL을 작성하시오.', '`employees` 테이블에는 `email` 컬럼이 있습니다. 이메일 주소에서 "@" 뒤의 도메인만 추출하여 조회하세요.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (60, '부서별 직원 이름을 하나의 문자열로 묶어 조회하는 SQL을 작성하시오.', '`employees` 테이블에서 같은 부서에 속한 직원들의 이름을 쉼표(,)로 구분하여 하나의 문자열로 묶어야 합니다. `GROUP_CONCAT()` 함수를 활용하세요.', 'MEDIUM', 1, '2025-03-19 15:30:33', 'Y'),
        (61, '각 반에서 최고 성적을 받은 학생의 ID, 이름, 점수를 조회하는 SQL을 작성하시오.', '서브쿼리를 활용하여 반별 최고 성적을 가진 학생을 찾는 방법을 묻는 문제입니다. 
  반별 최고 성적을 찾기 위해 서브쿼리를 사용하거나 RANK() 같은 윈도우 함수를 활용할 수도 있습니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (62, '특정 직원(employee_id = 5)의 모든 부하 직원을 조회하는 SQL을 작성하시오.', '이 문제는 재귀적 CTE(Common Table Expression, WITH RECURSIVE)를 활용하여 계층 구조를 탐색하는 문제입니다.
  부서 구조나 조직도를 표현할 때 자주 사용됩니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (63, '대용량 sales 테이블에서 월별 총 매출을 빠르게 조회하는 SQL을 작성하시오.', '이 문제는 파티션 테이블(Partition Table)을 활용하여 대용량 데이터의 성능을 최적화하는 방법을 묻습니다.
  월별 데이터를 파티셔닝한 상태에서 특정 월의 매출을 조회하는 SQL을 작성해야 합니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (64, '최근 3개월 동안의 평균 매출을 조회하는 SQL을 작성하시오.', '윈도우 함수 AVG()를 활용하여 최근 3개월 동안 평균적으로 발생한 매출을 계산하는 문제입니다. 
  LAG(), LEAD(), PARTITION BY 등을 적절히 활용해야 합니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (65, '지난 한 달 동안 가장 많이 판매된 상품을 조회하는 SQL을 작성하시오.', '서브쿼리를 활용하여 가장 많이 팔린 상품을 찾는 방법을 묻는 문제입니다. 
  RANK() 윈도우 함수를 활용하는 방식과 MAX()를 활용하는 방식이 있습니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (66, '고객 ID가 1001인 고객의 총 주문 금액을 조회하는 SQL을 작성하시오.', 'SUM()과 GROUP BY를 활용하여 특정 고객이 지금까지 주문한 총 금액을 계산하는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (67, '카테고리 테이블에서 특정 카테고리의 모든 하위 카테고리를 조회하는 SQL을 작성하시오.', '재귀적 CTE (WITH RECURSIVE)를 활용하여 계층 구조를 탐색하는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (68, '대용량 로그 테이블에서 특정 날짜의 사용자 활동 로그를 빠르게 조회하는 SQL을 작성하시오.', '파티션 테이블을 활용하여 특정 날짜에 대한 사용자 로그를 조회하는 문제입니다. 
  WHERE 절과 PARTITION을 조합해야 합니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (69, '최근 3개월 동안 각 고객의 매출 증가율을 계산하는 SQL을 작성하시오.', 'PARTITION BY와 LAG() 함수를 활용하여 각 고객의 매출이 전월 대비 얼마나 증가했는지 분석하는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (70, '카테고리별, 브랜드별, 전체 매출을 한 번의 쿼리로 조회하는 SQL을 작성하시오.', 'GROUPING SETS를 사용하여 다양한 수준의 집계 데이터를 동시에 구하는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (71, '단 한 번도 주문을 하지 않은 고객 목록을 조회하는 SQL을 작성하시오.', 'NOT EXISTS를 사용하여 주문 테이블에 존재하지 않는 고객을 찾는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (72, '각 부서별 직원의 연봉 순위를 계산하는 SQL을 작성하시오.', 'PARTITION BY와 RANK()를 활용하여 부서별 연봉 순위를 매기는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (73, '월별 매출과 전체 매출을 한 번의 쿼리로 조회하는 SQL을 작성하시오.', 'GROUPING SETS를 활용하여 월별 총 매출과 전체 매출을 동시에 출력하는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (74, '각 부서에서 가장 최근에 입사한 직원의 정보를 조회하는 SQL을 작성하시오.', 'PARTITION BY와 FIRST_VALUE() 함수를 사용하여 부서별로 가장 최근에 입사한 직원을 찾는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (75, '카테고리별, 브랜드별, 전체 판매량을 한 번의 쿼리로 조회하는 SQL을 작성하시오.', 'GROUPING SETS를 활용하여 다양한 수준의 판매량 집계를 동시에 조회하는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (76, '특정 제품(Product A)을 한 번도 구매하지 않은 고객 목록을 조회하는 SQL을 작성하시오.', 'NOT EXISTS를 사용하여 특정 제품을 구매한 적이 없는 고객을 찾는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (77, '학생별 최근 3회 시험 성적의 평균을 계산하는 SQL을 작성하시오.', 'PARTITION BY와 ROW_NUMBER()를 사용하여 최근 3회의 성적을 기준으로 평균을 구하는 문제입니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (78, 'GROUPING SETS란 무엇이며, ROLLUP 및 CUBE와의 차이점은 무엇인가?', 'GROUPING SETS는 다중 집계 수준을 한 번의 쿼리에서 수행할 수 있도록 하는 기능입니다. ROLLUP은 계층적 집계를 수행하고, CUBE는 가능한 모든 조합에 대해 집계를 수행하는 반면, GROUPING SETS는 특정한 집계 조합을 명시적으로 지정할 수 있습니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (79, '윈도우 함수와 일반 집계 함수의 차이점은 무엇인가?', '윈도우 함수는 OVER() 절을 사용하여 집계 결과를 개별 행에 유지하면서 수행할 수 있으며, 기존 행 데이터를 보존합니다. 반면, 일반 집계 함수는 여러 행을 하나의 결과로 축약합니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (80, 'NOT EXISTS와 LEFT JOIN을 활용한 필터링은 어떤 차이가 있는가?', 'NOT EXISTS는 서브쿼리에서 특정 조건을 만족하는 데이터가 존재하지 않는 경우를 필터링하는 반면, LEFT JOIN과 WHERE NULL을 사용하면 특정 테이블에 대응하는 데이터가 없는 경우를 찾을 수 있습니다. 하지만 LEFT JOIN은 불필요한 중복 데이터를 초래할 수 있어 성능에 영향을 줄 수 있습니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (81, 'PARTITION BY와 GROUP BY의 차이점은 무엇인가?', 'GROUP BY는 특정 컬럼을 기준으로 데이터를 그룹화하여 집계 값을 반환하는 반면, PARTITION BY는 윈도우 함수를 사용하여 개별 행을 보존하면서 그룹 내에서 연산을 수행할 수 있도록 합니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (82, '가장 많은 주문을 한 고객의 ID와 총 주문 횟수를 조회하는 SQL을 작성하시오.', '이 문제를 해결하려면 `COUNT(*)`를 사용하여 고객별 주문 횟수를 계산한 후, 서브쿼리를 사용하여 주문 횟수가 가장 높은 고객을 필터링해야 합니다. 즉, 주문 테이블에서 고객별 주문 횟수를 구한 뒤, 그 중 최대값을 찾고 해당 값을 가진 고객을 조회하면 됩니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (83, '각 직원의 급여가 해당 부서의 평균 급여보다 높은 직원의 ID, 이름, 급여를 조회하는 SQL을 작성하시오.', '각 직원의 급여가 속한 부서의 평균 급여보다 높은지 판단하려면 상관 서브쿼리를 사용해야 합니다. 즉, 메인 쿼리에서 개별 직원 데이터를 조회하고, 서브쿼리에서 해당 직원이 속한 부서의 평균 급여를 계산하여 비교하면 됩니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (84, '최근 3개월 동안 가장 많이 판매된 상품의 ID, 이름, 총 판매량을 조회하는 SQL을 작성하시오.', '이 문제를 해결하려면 먼저 주문 날짜를 기준으로 최근 3개월 데이터를 필터링한 후, 상품별 판매량을 계산해야 합니다. 그 다음, 서브쿼리를 사용하여 최대 판매량을 찾고 해당 값을 가진 상품을 조회하면 됩니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (85, '고객별 총 구매 금액을 계산하고, 특정 조건을 충족하는 고객에게 등급을 부여하는 SQL을 작성하시오.', '이 문제를 해결하려면 `SUM(order_amount)`을 사용하여 고객별 총 구매 금액을 계산한 후, 서브쿼리를 사용하여 각 고객의 총 구매 금액을 기반으로 등급을 부여해야 합니다. 예를 들어, 1000달러 이상 구매한 고객은 "VIP"로 분류하고, 500~999달러 구매한 고객은 "PREMIUM"으로, 그 이하는 "REGULAR"로 분류할 수 있습니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (86, '각 제품의 카테고리별 총 매출, 그리고 전체 총 매출을 동시에 조회하는 SQL을 작성하시오.', 'GROUPING SETS를 활용하면 단일 쿼리에서 여러 가지 집계 결과를 동시에 얻을 수 있습니다. 이 문제에서는 특정 그룹별 총 매출뿐만 아니라 전체 총 매출도 함께 계산해야 하므로, GROUP BY와 함께 GROUPING SETS를 적절히 사용해야 합니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (87, '한 번도 주문하지 않은 고객의 ID와 이름을 조회하는 SQL을 작성하시오.', 'NOT EXISTS는 특정 조건을 만족하지 않는 데이터를 찾을 때 유용하게 사용됩니다. 이 문제에서는 `customers` 테이블에 존재하지만, `orders` 테이블에 등장하지 않은 고객을 조회해야 합니다. 즉, 주문 정보가 없는 고객을 찾는 것이므로 NOT EXISTS 또는 LEFT JOIN과 NULL 체크를 활용할 수 있습니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (88, '각 직원이 속한 부서 내에서 자신의 급여 순위를 조회하는 SQL을 작성하시오.', '이 문제에서는 같은 부서 내에서 직원들의 급여 순위를 매겨야 하므로, RANK() 또는 DENSE_RANK()를 PARTITION BY와 함께 사용해야 합니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (89, '고객들이 한 번도 주문한 적이 없는 제품의 ID, 이름을 조회하는 SQL을 작성하시오.', '이 문제에서는 특정 제품이 주문된 적이 없는지 확인해야 하므로, NOT EXISTS를 활용하여 주문 테이블에 해당 제품이 존재하는지 체크해야 합니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y'),
        (90, '각 고객의 월별 총 구매 금액, 연도별 총 구매 금액을 동시에 조회하는 SQL을 작성하시오.', '이 문제에서는 GROUPING SETS를 사용하여 월별, 연도별 집계를 동시에 조회해야 합니다. 또한, PARTITION BY를 활용하면 개별 고객이 특정 월과 연도에서 구매한 총 금액을 구할 수 있습니다.', 'HARD', 1, '2025-03-19 15:30:38', 'Y');
        
