        (617, 78, 'GROUPING SETS는 특정한 집계 조합을 지정할 수 있으며, ROLLUP은 계층적 집계를 수행한다.', 1),
        (618, 78, 'ROLLUP과 CUBE는 동일한 기능을 수행하며, GROUPING SETS는 이를 포함하는 상위 개념이다.', 0),
        (619, 78, 'GROUPING SETS는 개별 열을 기준으로 자동 집계를 수행하는 기능이다.', 0),
        (620, 78, 'CUBE는 ROLLUP의 하위 개념이며, GROUPING SETS는 모든 가능한 조합을 집계한다.', 0),
        (621, 78, 'GROUPING SETS는 하나의 열만 집계할 수 있으며, 다중 열을 지원하지 않는다.', 0),
        (622, 78, 'ROLLUP과 GROUPING SETS는 동일한 기능을 수행하며, CUBE만 다르다.', 0),
        (623, 78, 'ROLLUP은 특정 컬럼에 대한 총합을 구할 때 사용되며, GROUPING SETS는 이를 최적화한 버전이다.', 0),
        (625, 79, '윈도우 함수는 개별 행을 보존하며, GROUP BY를 사용하지 않고도 집계 연산을 수행할 수 있다.', 1),
        (626, 79, '일반 집계 함수는 개별 행을 유지하며, 윈도우 함수는 데이터를 집계하여 하나의 값으로 축소한다.', 0),
        (627, 79, '윈도우 함수는 반드시 GROUP BY와 함께 사용해야 한다.', 0),
        (628, 79, '윈도우 함수는 단순히 SUM, COUNT와 같은 기본 연산을 수행하는 함수이다.', 0),
        (629, 79, '집계 함수는 WHERE 절과 함께 사용할 수 있지만, 윈도우 함수는 사용할 수 없다.', 0),
        (630, 79, '윈도우 함수는 단순히 데이터를 정렬하는 기능만을 수행한다.', 0),
        (631, 79, '일반 집계 함수는 행별로 계산되며, 윈도우 함수는 그룹 전체에 대해 한 번만 계산된다.', 0),
        (633, 80, 'NOT EXISTS는 특정 서브쿼리에 해당하는 행이 존재하지 않는 경우 TRUE를 반환한다.', 1),
        (634, 80, 'LEFT JOIN과 NOT EXISTS는 동일한 기능을 수행하며, 성능 차이는 거의 없다.', 0),
        (635, 80, 'NOT EXISTS는 INNER JOIN을 포함하는 경우에만 사용할 수 있다.', 0),
        (636, 80, 'LEFT JOIN을 사용하면 NOT EXISTS보다 성능이 향상된다.', 0),
        (637, 80, 'NOT EXISTS는 NULL 값을 허용하지 않으며, LEFT JOIN은 NULL을 포함할 수 있다.', 0),
        (638, 80, 'LEFT JOIN은 필터링을 위해 사용되지만, NOT EXISTS는 데이터 조회용으로만 사용된다.', 0),
        (639, 80, 'LEFT JOIN과 NOT EXISTS는 서브쿼리를 사용할 필요 없이 동일한 결과를 반환한다.', 0),
        (641, 81, 'PARTITION BY는 개별 행을 유지하며, 그룹 내에서 연산을 수행할 수 있다.', 1),
        (642, 81, 'GROUP BY는 개별 행을 보존하면서 그룹화된 데이터를 조회하는 기능을 제공한다.', 0),
        (643, 81, 'PARTITION BY는 그룹화된 데이터의 개수를 줄이는 역할을 한다.', 0),
        (644, 81, 'GROUP BY는 반드시 PARTITION BY와 함께 사용해야 한다.', 0),
        (645, 81, 'PARTITION BY는 SUM과 같은 집계 함수와 함께 사용할 수 없다.', 0),
        (646, 81, 'GROUP BY는 개별 행을 유지하면서 데이터를 정렬하는 기능을 한다.', 0),
        (647, 81, 'PARTITION BY는 GROUP BY의 상위 개념이며, 모든 집계 함수에 적용할 수 있다.', 0),
